INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein neues Modul immer eigenständig nutzbar?', 2, '[{"text": "Nein", "correct": true, "because": "Kann von Kernsoftware abhängen"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Plugin?', 3, '[{"text": "Funktionalität erweitern", "correct": true, "because": "Fügt spezifische Features hinzu"}, {"text": "Performance optimieren", "correct": false, "because": "Nicht primär"}, {"text": "UI überarbeiten", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Integration eines Moduls?', 5, '[{"text": "Kompatibilität prüfen", "correct": true, "because": "Sichert Funktion"}, {"text": "Installation testen", "correct": true, "because": "Verifiziert Stabilität"}, {"text": "Datenbank neu strukturieren", "correct": false, "because": "Nicht immer nötig"}, {"text": "Farbschema anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Plugins erweitern bestehende Software. b) Sie ersetzen den Kerncode.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Plugins ergänzen nur"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung eines Plugins?', 4, '[{"text": "Schnittstellendefinition", "correct": false, "because": "Muss kompatibel sein"}, {"text": "Dokumentation", "correct": false, "because": "Wichtig für Nutzung"}, {"text": "Farbanpassung der UI", "correct": true, "because": "Sekundär zur Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes System Plugins unterstützt?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind geschlossen"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um ein Modul zu testen?', 3, '[{"text": "Integrationstest", "correct": true, "because": "Prüft Zusammenspiel"}, {"text": "UI-Validierung", "correct": false, "because": "Nur Oberfläche"}, {"text": "Datenbankabfrage", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer Erweiterung entscheidend?', 5, '[{"text": "Stabilität", "correct": true, "because": "Vermeidet Abstürze"}, {"text": "Kompatibilität", "correct": true, "because": "Sichert Integration"}, {"text": "Schnelle Installation", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Optische Anpassung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Module müssen dokumentiert sein. b) Sie ändern die Hauptdatenbank. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "Datenbank nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Funktionserweiterung?', 4, '[{"text": "API-Dokumentation", "correct": false, "because": "Für Integration nötig"}, {"text": "Testumgebung", "correct": false, "because": "Prüft Funktion"}, {"text": "Grafikdesign", "correct": true, "because": "Kein funktionaler Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Plugins immer Open Source?', 2, '[{"text": "Nein", "correct": true, "because": "Können proprietär sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein neues Modul?', 4, '[{"text": "Erweiterte Features", "correct": true, "because": "Fügt Funktionen hinzu"}, {"text": "Flexibilität", "correct": true, "because": "Anpassung möglich"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Plugins die Performance senken. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Implementierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Erweiterung?', 3, '[{"text": "Kompatibilität sicherstellen", "correct": true, "because": "Integration essenziell"}, {"text": "Schnelle Bereitstellung", "correct": false, "because": "Qualität wichtiger"}, {"text": "UI-Optimierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Module erhöhen Flexibilität. b) Sie erfordern immer Neustart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neustart nicht immer nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei einer Funktionserweiterung?', 5, '[{"text": "Inkompatibilität", "correct": true, "because": "Kann System stören"}, {"text": "Fehleranfälligkeit", "correct": true, "because": "Neuer Code, neue Bugs"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Risiko"}, {"text": "UI-Verbesserung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Plugin unwichtig?', 3, '[{"text": "Schnittstellenkompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Testphase", "correct": false, "because": "Sichert Qualität"}, {"text": "Farbcodierung", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich ein Modul ohne Tests einführen?', 3, '[{"text": "Nein", "correct": true, "because": "Risiko für Fehler"}, {"text": "Ja", "correct": false, "because": "Tests essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Plugins immer klein sind?', 2, '[{"text": "Nein", "correct": true, "because": "Größe variiert"}, {"text": "Ja", "correct": false, "because": "Nicht festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzung wähle ich für ein neues Modul?', 4, '[{"text": "Definierte Schnittstelle", "correct": true, "because": "Integration ermöglichen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkaspekt"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}]');
